missing=[k for k in keys if k not in T]
extra=[k for k in T if k not in keys]
if missing: print("FALTAM:", missing); sys.exit(1)
if extra: print("sobrando (sem uso):", extra)
def esc(x): return x.replace('\\','\\\\').replace('"','\\"')

def write_lang(lang, table):
    import os
    os.makedirs(f"{sys.argv[2]}/{lang}.lproj", exist_ok=True)
    with open(f"{sys.argv[2]}/{lang}.lproj/Localizable.strings","w") as f:
        f.write(f"/* LlMBO — {lang}. Chaves = texto em português (idioma-base). Gerado a partir das chaves extraídas pelo compilador. */\n\n")
        for k in keys: f.write(f'"{esc(k)}" = "{esc(table[k])}";\n')

for i,lang in enumerate(["en","es"]):
    write_lang(lang, {k: T[k][i] for k in keys})

# --- Outros idiomas: Design/translations/<idioma>.json, com id → texto. Os ids ficam em keys.json (id → texto
# em português); texto novo ganha o próximo id sozinho. Sem tradução, o idioma usa o inglês e avisa.
import json, os, re
tdir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "translations")
ids = json.load(open(f"{tdir}/keys.json"))
by_text = {v: k for k, v in ids.items()}
grew = False
for k in keys:
    if k not in by_text:
        kid = f"k{len(ids) + 1:03d}"
        ids[kid] = k; by_text[k] = kid; grew = True
if grew:
    json.dump(ids, open(f"{tdir}/keys.json", "w"), ensure_ascii=False, indent=1)

# Os marcadores (%lld, %@, %%) precisam bater com o português, senão o app pode travar ao mostrar o texto.
def marks(x): return sorted(re.findall(r"%(?:\d+\$)?(lld|@|%)", x))

english = {k: T[k][0] for k in keys}
EXTRA = ["pt-PT", "fr", "de", "it", "nl", "pl", "tr", "ru", "uk", "ja", "ko", "zh-Hans", "zh-Hant",
         "hi", "id", "vi", "ar", "he"]
bad = []
for lang in EXTRA:
    tr = json.load(open(f"{tdir}/{lang}.json"))
    table, fallback = {}, []
    for k in keys:
        v = tr.get(by_text[k])
        if v is None:
            v = english[k]; fallback.append(by_text[k])
        if marks(v) != marks(k): bad.append(f"{lang} {by_text[k]}: {v}")
        table[k] = v
    write_lang(lang, table)
    if fallback: print(f"aviso: {lang} sem tradução para {fallback} (usa o inglês)")
# Variantes que só guardam as diferenças: inglês britânico (sobre o inglês) e espanhol latino-americano
# (sobre o espanhol).
spanish = {k: T[k][1] for k in keys}
for lang, base in [("en-GB", english), ("es-419", spanish)]:
    diff = json.load(open(f"{tdir}/{lang}.json"))
    table = {k: diff.get(by_text[k], base[k]) for k in keys}
    bad += [f"{lang} {by_text[k]}: {v}" for k, v in table.items() if marks(v) != marks(k)]
    write_lang(lang, table)
if bad: print("MARCADORES ERRADOS:", *bad, sep="\n  "); sys.exit(1)
print("ok", len(keys), "chaves,", 4 + len(EXTRA), "idiomas além do português")
